// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address depositor, uint256 depositAmount) public {
        vm.assume(uint160(depositor) > 255 && depositor != address(this) && depositor != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && depositor != 0x000000000000000000636F6e736F6c652e6c6f67 && depositor != 0x4e59b44847b379578588920cA78FbF26c0B4956C && depositor != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);

        depositAmount = bound(depositAmount, 0, 1 ether);
        vm.deal(depositor, depositAmount);

        if (depositAmount > 0) {
            vm.prank(depositor);
            (bool sent, ) = address(c).call{value: depositAmount}("");
            require(sent, "funding failed in test setup");
        }

        uint256 beforeBalance = address(c).balance;
        assert(beforeBalance == depositAmount);

        vm.prank(address(this));
        c.withdrawAll(depositor);

        assertTrue(address(c).balance == 0);
    }
}
